export function defaultExperienceSurface(surfaceKey: string, plane?: "studio" | "neon" | "mesh"): ExperienceSurface | undefined {
  return DEFAULT_EXPERIENCE_SURFACES.find((surface) => surface.id === surfaceKey && (!plane || surface.scope.plane === plane));
}
